const sentences = $input.first().json.message.content.sentences;
// Extract all languages
const languages = Object.keys(sentences);

// Get sentence counts for each language
const counts = {};
for (const lang of languages) {
  counts[lang] = sentences[lang].length;
}

// Check if all sentence counts are the same
const allEqual = Object.values(counts).every(
  (count) => count === Object.values(counts)[0]
);

// Return result
return {
  json: {
    allEqual,
    sentenceCounts: counts
  }
};

const script = $('Loop Over Items').first().json.script;

// Remove all double quotes in the script
const cleanedScript = script.replace(/\"/g, '');

return {
  json: {
    cleanedScript: cleanedScript
  }
};

const voiceIdsString = $('Start').first().json.voiceIds
const voideIds = voiceIdsString.split(',')
return {
  "voiceIds":voideIds
}

// Get the sentences object from the "write Script" node output
const sentences = $item(0).$node["write Script"].json.message.content.sentences;

// Define a separator that will never appear in normal text
const SEP = '\u001F';

// Create a compact key–value object: { "en": "sentence1␟sentence2", "de": "..." }
const result = {};
for (const [lang, arr] of Object.entries(sentences)) {
  result[lang] = arr.join(SEP);
}

// Return single JSON object for storing in Google Sheet
return { script: result };

const scriptJson = $('write Script').first().json || {};


const scriptArray = scriptJson?.message?.content?.script || {};
const titleArray = scriptJson?.message?.content?.title || {};
const descriptionArray = scriptJson?.message?.content?.description || {};
const tiktokTagsArray = scriptJson?.message?.content?.tiktok_tags || {};
const instaTagsArray = scriptJson?.message?.content?.instagram_tags || {};
const facebookTagsArray = scriptJson?.message?.content?.facebook_tags || {};
const youtubeTagsArray = scriptJson?.message?.content?.youtube_tags || {};
const voiceIds = $input.first().json.voiceIds

const languageKeys = Object.keys(scriptArray);
const finalJSON = [];

languageKeys.forEach((language, index) => {
  const itemJSON = {
    language,
    script: scriptArray[language] || '',
    title: titleArray[language] || '',
    description: descriptionArray[language] || '',
    tiktok_tags: tiktokTagsArray[language] || [],
    facebook_tags: facebookTagsArray[language] || [],
    instagram_tags: instaTagsArray[language] || [],
    youtube_tags: youtubeTagsArray[language] || [],
    voiceId: voiceIds[index] 
  };

  finalJSON.push(itemJSON);
});

return finalJSON;
